from __future__ import annotations

"""Causal WHY layer; consumes pre-hydrated App Ready evidence when available."""

_STYLE=r'''<style id="yipmanV1AllDecisionEvidenceStyle">.v1-detail-decision{cursor:pointer;touch-action:manipulation}.v1-decision-evidence{margin:0 0 9px;border:1px solid #314453;border-radius:14px;background:#101a22;overflow:hidden}.v1-decision-evidence>summary{list-style:none;cursor:pointer;padding:11px 12px;font-size:11px;font-weight:1000}.v1-decision-evidence-body{padding:10px 12px}.v1-decision-section{margin-bottom:10px}.v1-decision-section h4{margin:0 0 4px;color:#8194a3;font-size:8px}.v1-decision-section p{margin:0;color:#c0cbd3;font-size:11px;line-height:1.4}.v1-decision-grid{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:5px 9px;font-size:10px}.v1-decision-grid span{text-align:right;font-weight:900}.v1-decision-missing{color:#e3c36d!important}</style>'''
_SCRIPT=r'''<script id="yipmanV1AllDecisionEvidenceScript">(()=>{'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const txt=(r,s)=>String(r?.querySelector(s)?.textContent||'').trim();const norm=s=>String(s||'').toUpperCase().replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();const n=v=>{const x=parseFloat(String(v||'').replace(/[^0-9.-]/g,''));return Number.isFinite(x)?x:null};const metric=(r,...labels)=>{const wanted=labels.map(norm);for(const el of r.querySelectorAll('.v1-detail-metrics>div,.v1-force-order-cell,[data-evidence-key]')){const k=norm(el.dataset?.evidenceKey||txt(el,'b'));if(wanted.some(x=>k.includes(x)))return txt(el,'span')||el.dataset?.evidenceValue||''}return''};const id=(r,l)=>{for(const e of r.querySelectorAll('.v1-detail-id>div'))if(norm(txt(e,'b')).includes(norm(l)))return txt(e,'span');return''};function apply(force=false){const body=document.getElementById('v1DetailBody'),overlay=document.getElementById('v1DetailOverlay');if(!body||!overlay?.classList.contains('open'))return;const card=body.querySelector('.v1-detail-decision');if(!card)return;const action=txt(card,'strong'),sig=action+'|'+id(body,'FAMILY')+'|'+id(body,'UPC')+'|'+(body.dataset.appReadyDecision||'0');if(!force&&body.dataset.causalDecisionEvidence===sig)return;body.dataset.causalDecisionEvidence=sig;body.querySelectorAll('.v1-decision-evidence').forEach(x=>x.remove());const v={oh:metric(body,'EFFECTIVE OH','ORDERING OH USED'),pre:metric(body,'FORECAST USAGE BEFORE DELIVERY'),proj:metric(body,'PROJECTED OH AT DELIVERY'),usable:metric(body,'USABLE OH AT DELIVERY'),cov:metric(body,'FORECAST COVERAGE USAGE','COVERAGE DEMAND'),price:metric(body,'CURRENT PRICE'),suggested:metric(body,'SUGGESTED PRICE'),cost:metric(body,'CURRENT COST'),avg:metric(body,'7D AVG','DAILY FORECAST')};let trigger='Backend raised this action from current item state.',comparison='',math='',missing=[];if(/^NO ORDER|^ORDER/i.test(action)){trigger='Projected stock is compared with demand for the selected delivery window.';comparison=`Effective OH ${v.oh||'not exposed'}; pre-delivery usage ${v.pre||'not exposed'}; projected OH ${v.proj||'not exposed'}; coverage demand ${v.cov||'not exposed'}.`;const c=n(v.cov),a=n(v.usable)??n(v.proj);if(c!=null&&a!=null)math=`Raw need = max(0, ${c.toFixed(1)} − ${Math.max(0,a).toFixed(1)}) = ${Math.max(0,c-Math.max(0,a)).toFixed(1)}.`;else missing.push('ordering projection evidence')}else{trigger='Price review compares sustainable GP$/day against the current baseline.';const cp=n(v.price),sp=n(v.suggested),c=n(v.cost),av=n(v.avg);if(cp!=null&&sp!=null&&c!=null){const cm=cp-c,nm=sp-c,be=cm>0&&nm>0?cm/nm:null;comparison=`Current $${cp.toFixed(2)} margin $${cm.toFixed(2)}; proposed $${sp.toFixed(2)} margin $${nm.toFixed(2)}.`;if(be)math=`Break-even velocity = ${be.toFixed(2)}× baseline${av!=null?`; ≥ ${(av*be).toFixed(2)}/day`:''}.`}else missing.push('price/cost evidence')}const ev=[['Effective OH',v.oh],['Pre-delivery usage',v.pre],['Projected OH @ delivery',v.proj],['Coverage demand',v.cov],['Current price',v.price],['Suggested price',v.suggested],['Current cost',v.cost],['Velocity',v.avg]].filter(x=>x[1]);const box=document.createElement('details');box.className='v1-decision-evidence';box.open=true;box.innerHTML='<summary>WHY THIS EXACT DECISION</summary><div class="v1-decision-evidence-body"><section class="v1-decision-section"><h4>TRIGGER</h4><p>'+esc(trigger)+'</p></section><section class="v1-decision-section"><h4>COMPARISON</h4><p>'+esc(comparison)+'</p></section><section class="v1-decision-section"><h4>MATH</h4><p>'+esc(math||'Required numerical inputs are not exposed.')+'</p></section><section class="v1-decision-section"><h4>EVIDENCE</h4><div class="v1-decision-grid">'+ev.map(x=>'<b>'+esc(x[0])+'</b><span>'+esc(x[1])+'</span>').join('')+'</div></section><section class="v1-decision-section"><h4>DECISION</h4><p>'+esc(action)+'</p>'+(missing.length?'<p class="v1-decision-missing">Missing: '+esc(missing.join('; '))+'</p>':'')+'</section><section class="v1-decision-section"><h4>SOURCE</h4><p>'+(body.dataset.appReadyDecision==='1'?'Pre-analyzed App Ready snapshot; no business recomputation on open.':'Visible FULL MYSQL detail; App Ready evidence unavailable.')+'</p></section></div>';card.insertAdjacentElement('afterend',box);card.onclick=()=>box.open=!box.open}let q=false;const kick=()=>{if(q)return;q=true;requestAnimationFrame(()=>{q=false;apply()})};new MutationObserver(kick).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});document.addEventListener('yipman-app-ready-decision-hydrated',()=>apply(true));document.addEventListener('click',()=>setTimeout(kick,0),true)})();</script>'''
def polish_all_decision_evidence_html(html:str)->str:
    if 'yipmanV1AllDecisionEvidenceStyle' in html:return html
    return html.replace('</head>',_STYLE+'</head>',1).replace('</body>',_SCRIPT+'</body>',1)
